from jsonb_to_recordset($catalogue_seed$[{"source_id":"DB_004","pilot":{"sourceId":"DB_004","sourceVersion":"1.2.0","sourceCatalogVersion":"4.0.0-unified.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Squat bulgare gobelet","en":"Dumbbell goblet Bulgarian split squat"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Tenez un haltère en gobelet et placez le pied arrière sur le banc, pied avant au sol.","execution":"Descendez le bassin entre les deux pieds en fléchissant les genoux, sans déplacer les appuis.","finish":"Poussez principalement dans le pied avant pour retrouver la position haute."},"en":{"setup":"Hold one dumbbell at your chest with the rear foot supported on the bench and the front foot planted.","execution":"Lower your hips between your feet by bending both knees, without shifting the foot positions.","finish":"Drive mainly through the front foot to return to the upright split stance."}},"performance":{"measure":"repetitions","counting":{"fr":"Convention proposée: une répétition comprend une descente et une remontée en fente fixe, appuis inchangés. La mise en place et la sortie après série ne comptent pas de répétition supplémentaire. Compter séparément chaque côté; aucun changement de côté sous charge n’est ajouté.","en":"Proposed convention: one repetition consists of one lowering and rise in the fixed split stance, with unchanged foot positions. Setup and the exit after the set do not add repetitions. Count each side separately; no loaded side change is added."},"load":{"fr":"Saisir la masse réelle de chaque haltère, unité explicite, sans ajouter le poids du corps. Deux mains sur un seul haltère ne doublent pas sa masse.","en":"Enter the actual mass of each dumbbell with an explicit unit, excluding body mass. Holding one dumbbell with two hands does not double its mass."},"countingDecision":"PROPOSED","notes":{"fr":"Fiche éditoriale à vérifier, utilisable uniquement pour les essais staging. Aucun modèle de machine ni média n’est approuvé. Aucune résistance réelle n’est calculée automatiquement.","en":"Editorial exercise requiring review, for staging tests only. No machine model or media is approved. Actual resistance is never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"DB_012","pilot":{"sourceId":"DB_012","sourceVersion":"1.1.0","sourceCatalogVersion":"4.0.0-unified.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Soulevé de terre roumain à une jambe, charge opposée","en":"Contralateral single-leg dumbbell Romanian deadlift"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Tenez l’haltère dans la main opposée à la jambe d’appui, sans appui externe.","execution":"Basculez à la hanche de la jambe d’appui en laissant l’autre jambe partir derrière, bassin contrôlé.","finish":"Revenez debout sur la jambe active sans transformer le retour en rotation du bassin."},"en":{"setup":"Hold the dumbbell in the hand opposite your standing leg, without external support.","execution":"Hinge at the standing hip as the free leg reaches backward, keeping your pelvis controlled.","finish":"Return to standing on the working leg without twisting your pelvis."}},"performance":{"measure":"repetitions","counting":{"fr":"Convention proposée: une répétition comprend une charnière sur la jambe d’appui puis le retour debout sur cette jambe. La mise en place et la sortie après série ne comptent pas de répétition supplémentaire. Compter séparément chaque côté; aucun changement de côté sous charge n’est ajouté.","en":"Proposed convention: one repetition consists of a hinge on the standing leg and return to standing on that leg. Setup and the exit after the set do not add repetitions. Count each side separately; no loaded side change is added."},"load":{"fr":"Saisir la masse réelle de chaque haltère, unité explicite, sans ajouter le poids du corps. Deux mains sur un seul haltère ne doublent pas sa masse.","en":"Enter the actual mass of each dumbbell with an explicit unit, excluding body mass. Holding one dumbbell with two hands does not double its mass."},"countingDecision":"PROPOSED","notes":{"fr":"Fiche éditoriale à vérifier, utilisable uniquement pour les essais staging. Aucun modèle de machine ni média n’est approuvé. Aucune résistance réelle n’est calculée automatiquement.","en":"Editorial exercise requiring review, for staging tests only. No machine model or media is approved. Actual resistance is never calculated automatically."},"loadEntryBasis":"per_implement"}},"default_unit":"lb"},{"source_id":"DB_013","pilot":{"sourceId":"DB_013","sourceVersion":"1.1.0","sourceCatalogVersion":"4.0.0-unified.1","integrationVersion":"fe-program-pilot.1","usage":"STAGING_TEST","name":{"fr":"Extension de hanches avec haltère sur banc","en":"Dumbbell hip thrust"},"equipment":{"id":"dumbbell","labels":{"fr":"Haltères","en":"Dumbbells"}},"instructions":{"fr":{"setup":"Appuyez le haut du dos sur le banc et maintenez un haltère sur le bassin, deux pieds au sol.","execution":"Étendez les hanches en gardant les appuis et la charge sur le bassin stables, sans cambrer pour gagner de la hauteur.","finish":"Redescendez le bassin sous contrôle jusqu’au départ, sans déplacer le haut du dos."},"en":{"setup":"Support your upper back on the bench and secure one dumbbell across your hips with both feet planted.","execution":"Extend your hips while keeping the supports and pelvic load steady, without arching your back to gain height.","finish":"Lower your hips under control to the start without sliding your upper back."}},"performance":{"measure":"repetitions","counting":{"fr":"Convention proposée: une répétition comprend une élévation puis un abaissement du bassin avec le haut du dos sur le banc. La mise en place et la sortie après série ne comptent pas de répétition supplémentaire.","en":"Proposed